package net.civeira.phylax.feature.template.templateversion.application.usecase.update;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.template.template.domain.TemplateReference;
import net.civeira.phylax.feature.template.templateversion.domain.TemplateVersionChangeSet;

class TemplateVersionUpdateInputUnitTest {

  /**
   * @autogenerated UpdateInputGenerator
   */
  @Test
  @DisplayName("Test the template version input values are kept when converted to a change set and back")
  void test_template_version_update_input_change_set_round_trip() {
    TemplateVersionUpdateInput input =
        TemplateVersionUpdateInput.builder().uid("one").template(TemplateReference.of("one"))
            .locale("one").subject("one").contentHtml("one").contentText("one").version(1).build();
    TemplateVersionChangeSet changes = input.toChangeSet();
    Assertions.assertNotNull(changes, "A change set must be created");
    TemplateVersionUpdateInput copy = TemplateVersionUpdateInput.fromChangeSet(changes);
    Assertions.assertTrue(input.getUid().isPresent(), "uid must be assigned by the builder");
    Assertions.assertEquals(input.getUid(), copy.getUid(),
        "uid must survive the change set round trip");
    Assertions.assertTrue(input.getTemplate().isPresent(),
        "template must be assigned by the builder");
    Assertions.assertEquals(input.getTemplate(), copy.getTemplate(),
        "template must survive the change set round trip");
    Assertions.assertTrue(input.getLocale().isPresent(), "locale must be assigned by the builder");
    Assertions.assertEquals(input.getLocale(), copy.getLocale(),
        "locale must survive the change set round trip");
    Assertions.assertTrue(input.getSubject().isPresent(),
        "subject must be assigned by the builder");
    Assertions.assertEquals(input.getSubject(), copy.getSubject(),
        "subject must survive the change set round trip");
    Assertions.assertTrue(input.getContentHtml().isPresent(),
        "contentHtml must be assigned by the builder");
    Assertions.assertEquals(input.getContentHtml(), copy.getContentHtml(),
        "contentHtml must survive the change set round trip");
    Assertions.assertTrue(input.getContentText().isPresent(),
        "contentText must be assigned by the builder");
    Assertions.assertEquals(input.getContentText(), copy.getContentText(),
        "contentText must survive the change set round trip");
    Assertions.assertTrue(input.getVersion().isPresent(),
        "version must be assigned by the builder");
    Assertions.assertEquals(input.getVersion(), copy.getVersion(),
        "version must survive the change set round trip");
  }

  /**
   * @autogenerated UpdateInputGenerator
   */
  @Test
  @DisplayName("Test the template version input builder can generate a new identifier")
  void test_template_version_update_input_new_uid() {
    TemplateVersionUpdateInput input = TemplateVersionUpdateInput.builder().newUid().build();
    Assertions.assertTrue(input.getUid().isPresent(), "A new uid must be generated");
    Assertions.assertTrue(input.getVersion().isPresent(), "The initial version must be assigned");
    Assertions.assertNotEquals(input.getUid(),
        TemplateVersionUpdateInput.builder().newUid().build().getUid(),
        "Each new uid must be different");
  }

  /**
   * @autogenerated UpdateInputGenerator
   */
  @Test
  @DisplayName("Test the template version input starts empty and the setters assign values")
  void test_template_version_update_input_setters() {
    TemplateVersionUpdateInput empty = TemplateVersionUpdateInput.builder().build();
    Assertions.assertTrue(empty.getUid().isEmpty(), "uid must be empty by default");
    Assertions.assertSame(empty, empty.setUid("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getUid().isPresent(), "uid must be assigned by the setter");
    Assertions.assertTrue(empty.getTemplate().isEmpty(), "template must be empty by default");
    Assertions.assertSame(empty, empty.setTemplate(TemplateReference.of("one")),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getTemplate().isPresent(),
        "template must be assigned by the setter");
    Assertions.assertTrue(empty.getLocale().isEmpty(), "locale must be empty by default");
    Assertions.assertSame(empty, empty.setLocale("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getLocale().isPresent(), "locale must be assigned by the setter");
    Assertions.assertTrue(empty.getSubject().isEmpty(), "subject must be empty by default");
    Assertions.assertSame(empty, empty.setSubject("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getSubject().isPresent(), "subject must be assigned by the setter");
    Assertions.assertTrue(empty.getContentHtml().isEmpty(), "contentHtml must be empty by default");
    Assertions.assertSame(empty, empty.setContentHtml("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getContentHtml().isPresent(),
        "contentHtml must be assigned by the setter");
    Assertions.assertTrue(empty.getContentText().isEmpty(), "contentText must be empty by default");
    Assertions.assertSame(empty, empty.setContentText("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getContentText().isPresent(),
        "contentText must be assigned by the setter");
    Assertions.assertTrue(empty.getVersion().isEmpty(), "version must be empty by default");
    Assertions.assertSame(empty, empty.setVersion(1), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getVersion().isPresent(), "version must be assigned by the setter");
    Assertions.assertNotNull(empty.toChangeSet(), "A change set must be created");
  }
}
